import{_ as i,a as n,c as l,ac as o}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"第四册：流利英语 · 单元 4：机制、反事实与专业沟通","description":"L25–L32 的学习目标、课时入口和复习方法。","frontmatter":{"title":"第四册：流利英语 · 单元 4：机制、反事实与专业沟通","description":"L25–L32 的学习目标、课时入口和复习方法。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","summary":"L25–L32 的学习目标、课时入口和复习方法。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · 单元 3 复习与自测","link":"/life/english/new-concept/book-4/unit-03/review"},"next":{"text":"第四册：流利英语 · 单元 4 语法总结","link":"/life/english/new-concept/book-4/unit-04/grammar"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · 单元 3 复习与自测","link":"/life/english/new-concept/book-4/unit-03/review"},"next":{"text":"第四册：流利英语 · 单元 4 语法总结","link":"/life/english/new-concept/book-4/unit-04/grammar"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-04/overview.md","filePath":"life/english/new-concept/book-4/unit-04/overview.md"}'),a={name:"life/english/new-concept/book-4/unit-04/overview.md"};function t(s,e,r,c,h,u){return n(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-单元-4-机制、反事实与专业沟通" tabindex="-1">第四册：流利英语 · 单元 4：机制、反事实与专业沟通 <a class="header-anchor" href="#第四册-流利英语-·-单元-4-机制、反事实与专业沟通" aria-label="Permalink to &quot;第四册：流利英语 · 单元 4：机制、反事实与专业沟通&quot;">​</a></h1><p><a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-04/overview">单元导读</a> · <a href="/life/english/new-concept/book-4/unit-04/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-4/unit-04/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-4/unit-04/review">单元复习与自测</a></p><h2 id="单元导读" tabindex="-1">单元导读 <a class="header-anchor" href="#单元导读" aria-label="Permalink to &quot;单元导读&quot;">​</a></h2><p>L25–L32。第25—32课从噪声、地球历史、沉船、医患沟通、气垫船、海底探索、雕塑和科学争论展开。重点是在专业词汇之外讲清过程：什么先发生、谁执行动作、仪器在何种条件下工作，以及另一种历史结果只是怎样的假设。将抽象名词还原为动作，将长句还原为主干，再根据读者需要重新组合为清楚的说明。</p><p>本栏目按连续课号组织学习单元；单元主题与复习任务为本站编排，便于分阶段学习，不作为各印次教材目录的替代。</p><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>还原名词化和分词压缩的信息</li><li>使用过去反事实和间接问句</li><li>说明装置功能及研究限制</li></ul><h2 id="课时目录" tabindex="-1">课时目录 <a class="header-anchor" href="#课时目录" aria-label="Permalink to &quot;课时目录&quot;">​</a></h2><ul><li><a href="/life/english/new-concept/book-4/unit-04/lesson-025">Lesson 25 · Non-auditory effects of noise</a></li><li><a href="/life/english/new-concept/book-4/unit-04/lesson-026">Lesson 26 · The past life of the earth</a></li><li><a href="/life/english/new-concept/book-4/unit-04/lesson-027">Lesson 27 · The &#39;Vasa&#39;</a></li><li><a href="/life/english/new-concept/book-4/unit-04/lesson-028">Lesson 28 · Patients and doctors</a></li><li><a href="/life/english/new-concept/book-4/unit-04/lesson-029">Lesson 29 · The hovercraft</a></li><li><a href="/life/english/new-concept/book-4/unit-04/lesson-030">Lesson 30 · Exploring the sea-floor</a></li><li><a href="/life/english/new-concept/book-4/unit-04/lesson-031">Lesson 31 · The sculptor speaks</a></li><li><a href="/life/english/new-concept/book-4/unit-04/lesson-032">Lesson 32 · Galileo reborn</a></li></ul><h2 id="单元知识地图" tabindex="-1">单元知识地图 <a class="header-anchor" href="#单元知识地图" aria-label="Permalink to &quot;单元知识地图&quot;">​</a></h2><ul><li>L25：名词化与施事信息。exposure of noise 应改 exposure to noise；coincided with 也不能自动替换为 caused。</li><li>L26：完成式分词状语。Having compared the layers, a sequence was proposed 容易让 sequence 成为比较者；应明确主语 researchers。</li><li>L27：第三条件句与过去反事实。If the model would have been tested 错把结果形式放入条件；应写 had been tested。</li><li>L28：间接问句与疑问语序。Could you explain what does this term mean? 错用直接问句语序；应去 does 并用 means。</li><li>L29：使役与许可结构。allows the model move 缺少 to；不要把 allow 的结构误套成 make 的结构。</li><li>L30：介词 + which 的关系从句。under that the sensor operates 不成立；介词前置的关系结构用 which。</li><li>L31：独立主格的主语与分词。不要把独立主格误写成 The clay was still damp, the sculptor covered…；两个完整句不能仅用逗号连接。</li><li>L32：形容词前置的 as 让步结构。As the evidence is limited 通常更容易读成“因为证据有限”；要保留让步意思可用 Although 或前置 Limited as。</li></ul><h2 id="完成标准" tabindex="-1">完成标准 <a class="header-anchor" href="#完成标准" aria-label="Permalink to &quot;完成标准&quot;">​</a></h2><p>能用自己的例子说明上面的语法点；能在不看答案时完成单元自测；能完成至少一项口头表达和一项书面表达，并根据课时点评修订。若做错，不必整单元重学，沿题目链接回到相应课时。</p>',13)])])}const f=i(a,[["render",t]]);export{d as __pageData,f as default};
